// A sparkline: samples over time as one line, drawn by CSS. No SVG and no canvas: every item owns the segment back to the
// sample before it — a 2px bar as long as hypot(step, dy) and turned by atan2(dy, step) — so its thickness stays even
// however steep the line is. The markup is an ordered list of numbers; with the stylesheet off it still reads as one.
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the list, `data-part` and the caller's class merged in. */
export type SparklinePartProps = PartProps;

export interface SparklineProps extends Renderable<SparklinePartProps, void> {
  /** The samples, oldest first: each is a point, and the line joins it to the one before it. */
  readonly values: ReadonlyArray<number>;
  /** The list's name, which is also what a reader hears: "Requests per second, the last 20 samples". */
  readonly label: string;
  /** The bottom of the scale; left out, the smallest sample. */
  readonly min?: number;
  /** The top of the scale; left out, the largest sample. */
  readonly max?: number;
  /** The rail's height, a CSS length. @default "3rem" */
  readonly height?: string;
  /** `accent` draws in the highlight colour, `muted` in the second text colour. */
  readonly tone?: "accent" | "muted";
  /** A sample as a reader sees it on hover; left out, the number itself. */
  readonly format?: (value: number) => string;
  readonly class?: string;
}

// The list is the plot. Its items share the width evenly, and each is a size container so its children can measure it in
// `cqw`/`cqh`. The count is `--n` and not `sibling-count()`: the caller knows how many samples it has, and the CSS function
// is new enough that a target without it would lose the first item's half-step offset.
const list = css.cn(
  css.display("flex"),
  css.alignItems("stretch"),
  css.width("100%"),
  css.margin(0),
  css.padding(0),
  css.listStyle("none"),
  css.position("relative"),
);

// The item is one sample's column: the point sits on its middle, and its `::before` is the segment that arrives at it. The
// first column hangs back half a step, so the line starts at the rail's left edge; the count is `--n` and not
// `sibling-count()`, because the caller knows how many samples it has.
const sample = css.cn(
  // `group()` is the marker the value label reads with `within(hover)`; the marks themselves are pseudo-elements of this
  // item, so their state is the item's own (`hover(after(...))`).
  css.group(),
  css.flex("1"),
  css.minWidth("0"),
  css.position("relative"),
  css.containerType("size"),
  css.firstChild(css.marginLeft("calc(-50% / var(--n))")),
  // the segment back to the previous sample: from the previous point, 2px thick and as long as the distance between the two
  css.before(
    css.content('""'),
    css.position("absolute"),
    css.height("2px"),
    css.left("calc(-50cqw - 1px)"),
    css.bottom("calc(var(--y0) * 100% - 1px)"),
    css.width("calc(hypot(100cqw, (var(--y1) - var(--y0)) * 100cqh) + 3px)"),
    css.transformOrigin("1px 50%"),
    css.rotate("calc(atan2((var(--y0) - var(--y1)) * 100cqh, 100cqw))"),
    css.borderRadius("1px"),
    css.bg(t.color.highlight),
  ),
  // the dot on this sample: shown while the sample is hovered, and always on the last one (the line's head)
  css.after(
    css.content('""'),
    css.boxSizing("border-box"),
    css.position("absolute"),
    css.left("50%"),
    css.bottom("calc(var(--y1) * 100% - 3px)"),
    css.width("6px"),
    css.height("6px"),
    css.marginLeft("-3px"),
    css.borderRadius("999px"),
    css.border("2px solid", t.color.surface),
    css.bg(t.color.highlight),
    css.opacity(0),
  ),
  css.hover(css.after(css.opacity(1))),
  css.lastChild(css.after(css.opacity(1))),
);

// The quiet tone repaints both marks and changes nothing else.
const sampleMuted = css.cn(
  sample,
  css.before(css.bg(t.color.muted)),
  css.after(css.bg(t.color.muted)),
);

// The value above its point, while the sample is hovered: `pointer-events: none` keeps it from stealing the hover, and the
// room it needs is the item's own, so nothing moves.
const value = css.cn(
  css.position("absolute"),
  css.left("50%"),
  css.bottom("calc(var(--y1) * 100% + 6px)"),
  css.transform("translateX(-50%)"),
  css.padding("2px 6px"),
  css.borderRadius("4px"),
  css.whiteSpace("nowrap"),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.text),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.opacity(0),
  css.pointerEvents("none"),
  css.within(css.hover)(css.opacity(1)),
);

// The frame and its caption: a chart reads as a named figure, and the caption says in words what the line shows — the range
// and the two extremes — so a reader who cannot hover (a keyboard, a screen reader, a printed page) still gets the shape.
const frame = css.cn(css.display("grid"), css.width("100%"), css.margin(0), css.gap(t.space._1));
const caption = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));

const number = (sampleValue: number): string => String(sampleValue);

/**
 * A sparkline: the last samples of a series, one line, and the value under the pointer.
 *
 * The scale is the caller's (`min`/`max`) or the samples' own, so two sparklines that read against the same axis say so.
 * The normalised heights are computed in CSS from `--min` and `--max`: the markup carries the numbers a reader would want,
 * not percentages.
 */
export const Sparkline = (props: SparklineProps): JSX.Element => {
  const low = (): number => props.min ?? Math.min(...props.values);
  const high = (): number => {
    const top = props.max ?? Math.max(...props.values);
    // a flat line has no range to divide by: give it one, so every point sits on the middle of the rail
    return top === low() ? low() + 1 : top;
  };
  const samples = (): ReadonlyArray<number> => props.values;
  const mutedTone = (): boolean => props.tone === "muted";
  const format = (sampleValue: number): string => (props.format ?? number)(sampleValue);
  // "from 1310 to 1350, lowest 1310, highest 1530": the first and last samples, then the extremes
  const summary = (): string => {
    const all = samples();
    const first = all[0];
    const last = all.at(-1);
    if (first === undefined || last === undefined) return "";
    const lowest = Math.min(...all);
    const highest = Math.max(...all);
    return `from ${format(first)} to ${format(last)}; lowest ${format(lowest)}, highest ${format(highest)}`;
  };

  const own = {
    "data-part": "sparkline",
    get class() {
      return css.cn(list, props.class);
    },
    get style() {
      return {
        "--min": low(),
        "--max": high(),
        "--n": Math.max(1, samples().length),
        height: props.height ?? "3rem",
      } as never;
    },
  } as unknown as PartProps;

  return (
    <figure data-part="sparkline-frame" class={frame}>
      <figcaption data-part="sparkline-caption" class={caption}>
        {props.label}
        {samples().length === 0 ? "" : `. ${summary()}`}
      </figcaption>
      {renderPart(props, own, undefined, (part) => (
        <ol {...part} aria-label={props.label}>
          <For each={samples()}>
            {(sampleValue, index) => {
              const before = (): number => samples()[index() - 1] ?? sampleValue;
              return (
                <li
                  data-part="sparkline-sample"
                  class={mutedTone() ? sampleMuted : sample}
                  style={
                    {
                      "--a": before(),
                      "--b": sampleValue,
                      "--y0": "calc((var(--a) - var(--min)) / (var(--max) - var(--min)))",
                      "--y1": "calc((var(--b) - var(--min)) / (var(--max) - var(--min)))",
                    } as never
                  }
                >
                  <data value={number(sampleValue)} class={value} data-part="sparkline-value">
                    {(props.format ?? number)(sampleValue)}
                  </data>
                </li>
              );
            }}
          </For>
        </ol>
      ))}
    </figure>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The sparkline's conformance: the list is the data, and the line is CSS. The tests read what a reader gets — one item per
// sample with its number, a segment turned by an angle and as long as the distance, a value that appears on hover — rather
// than the stylesheet that produced it.
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { Sparkline } from "./sparkline.tsx";

const mount = (element: () => JSX.Element) => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(element, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const items = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="sparkline-sample"]'),
];

describe("Sparkline", () => {
  it("is a named figure whose caption says what the line shows, without a pointer", () => {
    const { root, dispose } = mount(() => (
      <Sparkline label="Requests per second" values={[1310, 1490, 1350]} />
    ));
    const caption = root.querySelector("figcaption")?.textContent ?? "";
    // the label, then the range in words: a keyboard user and a printed page get the shape
    expect(caption).toContain("Requests per second");
    expect(caption).toContain("from 1310 to 1350; lowest 1310, highest 1490");
    expect(root.querySelector("figure")).not.toBeNull();
    dispose();
  });

  it("draws one item per sample, with the number as its data", () => {
    const { root, dispose } = mount(() => <Sparkline label="Requests" values={[3, 5, 4, 6]} />);
    const rows = items(root);
    expect(rows).toHaveLength(4);
    expect(rows.map((row) => row.querySelector("data")?.getAttribute("value"))).toEqual([
      "3",
      "5",
      "4",
      "6",
    ]);
    // the two values a segment is turned from: the sample and the one before it
    expect(rows[2]?.style.getPropertyValue("--b")).toBe("4");
    expect(rows[2]?.style.getPropertyValue("--a")).toBe("5");
    // the first sample has no previous one: it starts on itself, so its segment is flat
    expect(rows[0]?.style.getPropertyValue("--a")).toBe("3");
    expect(root.querySelector("ol")?.getAttribute("aria-label")).toBe("Requests");
  });

  it("draws the segment as the item's ::before, turned and as long as the step", () => {
    const { root, dispose } = mount(() => (
      <Sparkline label="Requests" values={[0, 10]} height="100px" />
    ));
    const rows = items(root);
    const segment = getComputedStyle(rows[1]!, "::before");
    // the pseudo-element exists and paints itself: `content` is what makes a ::before a box
    expect(segment.content).toBe('""');
    expect(segment.backgroundColor).not.toBe("rgba(0, 0, 0, 0)");
    // a rising line turns the bar; the computed value is an angle, not `none`
    expect(segment.rotate).toMatch(/-?[\d.]+(deg|grad|rad|turn)/);
    // the bar is longer than its 2px thickness: it spans the step horizontally and the rise vertically
    expect(Number.parseFloat(segment.width)).toBeGreaterThan(2);
    dispose();
  });

  it("shows a sample's value and dot on hover, and the head's dot always", async () => {
    const { root, dispose } = mount(() => <Sparkline label="Requests" values={[1, 4, 2]} />);
    const rows = items(root);
    const value = (row: HTMLElement): HTMLElement => row.querySelector<HTMLElement>("data")!;
    const dot = (row: HTMLElement): CSSStyleDeclaration => getComputedStyle(row, "::after");

    expect(getComputedStyle(value(rows[1]!)).opacity).toBe("0");
    expect(dot(rows[1]!).opacity).toBe("0");
    await userEvent.hover(rows[1]!);
    expect(getComputedStyle(value(rows[1]!)).opacity).toBe("1");
    expect(dot(rows[1]!).opacity).toBe("1");
    // the last sample's dot is the line's head: it is drawn without a hover
    expect(dot(rows[2]!).opacity).toBe("1");
    expect(dot(rows[2]!).content).toBe('""');
    dispose();
  });

  it("takes the scale from the samples, or from the page when it shares one", () => {
    const own = mount(() => <Sparkline label="Requests" values={[10, 20, 30]} />);
    const list = own.root.querySelector<HTMLElement>("ol")!;
    expect(list.style.getPropertyValue("--min")).toBe("10");
    expect(list.style.getPropertyValue("--max")).toBe("30");
    own.dispose();

    const shared = mount(() => <Sparkline label="Requests" values={[10, 20]} min={0} max={100} />);
    const other = shared.root.querySelector<HTMLElement>("ol")!;
    expect(other.style.getPropertyValue("--min")).toBe("0");
    expect(other.style.getPropertyValue("--max")).toBe("100");
    shared.dispose();
  });

  it("gives a flat line a range, so every point sits on the rail", () => {
    const { root, dispose } = mount(() => <Sparkline label="Requests" values={[7, 7, 7]} />);
    const list = root.querySelector<HTMLElement>("ol")!;
    expect(list.style.getPropertyValue("--min")).toBe("7");
    expect(list.style.getPropertyValue("--max")).toBe("8");
    dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
